#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *buf;
    size_t capacity;
    size_t head; /* write index */
    size_t tail; /* read index */
    size_t count;
};

ringbuf_t *rb_create(size_t capacity) {
    if (capacity == 0)
        return NULL;
    ringbuf_t *rb = malloc(sizeof(ringbuf_t));
    if (!rb)
        return NULL;
    rb->buf = malloc(capacity);
    if (!rb->buf) {
        free(rb);
        return NULL;
    }
    rb->capacity = capacity;
    rb->head = 0;
    rb->tail = 0;
    rb->count = 0;
    return rb;
}

static void rb_init(ringbuf_t *rb) {
    rb->head = 0;
    rb->tail = 0;
    rb->count = 0;
}

void rb_destroy(ringbuf_t *rb) {
    if (!rb)
        return;
    free(rb->buf);
    free(rb);
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len) {
    if (!rb || !data || len == 0)
        return 0;
    size_t free_space = rb->capacity - rb->count;
    size_t n = len < free_space ? len : free_space;

    /* Write to fill from head wrapping around */
    size_t first_chunk = n;
    if (first_chunk > rb->capacity - rb->head)
        first_chunk = rb->capacity - rb->head;

    memcpy(rb->buf + rb->head, data, first_chunk);
    if (n > first_chunk)
        memcpy(rb->buf, data + first_chunk, n - first_chunk);

    rb->head = (rb->head + n) % rb->capacity;
    rb->count += n;
    return n;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len) {
    if (!rb || !out || len == 0)
        return 0;
    if (rb->count == 0)
        return 0;
    size_t n = len < rb->count ? len : rb->count;

    size_t first_chunk = n;
    if (first_chunk > rb->capacity - rb->tail)
        first_chunk = rb->capacity - rb->tail;

    memcpy(out, rb->buf + rb->tail, first_chunk);
    if (n > first_chunk)
        memcpy(out + first_chunk, rb->buf, n - first_chunk);

    rb->tail = (rb->tail + n) % rb->capacity;
    rb->count -= n;
    return n;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len) {
    if (!rb || !out || len == 0)
        return 0;
    if (rb->count == 0)
        return 0;
    size_t n = len < rb->count ? len : rb->count;
    size_t tmp_head = rb->head;
    size_t tmp_tail = rb->tail;

    /* Copy without mutating the buffer */
    size_t first_chunk = n;
    if (first_chunk > rb->capacity - tmp_tail)
        first_chunk = rb->capacity - tmp_tail;

    memcpy(out, rb->buf + tmp_tail, first_chunk);
    if (n > first_chunk)
        memcpy(out + first_chunk, rb->buf, n - first_chunk);

    return n;
}

size_t rb_size(const ringbuf_t *rb) {
    if (!rb)
        return 0;
    return rb->count;
}

size_t rb_capacity(const ringbuf_t *rb) {
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb) {
    if (!rb)
        return;
    rb_init(rb);
}

#include <stdio.h>
#include <string.h>
#include "ringbuf.h"

int main(void) {
    int failed = 0;

    /* Create */
    ringbuf_t *rb = rb_create(8);
    if (!rb || rb_capacity(rb) != 8) { printf("FAIL: create\n"); return 1; }

    /* Clear and size */
    rb_clear(rb);
    if (rb_size(rb) != 0) { printf("FAIL: clear/size\n"); return 1; }

    /* Write 5 bytes, read them back */
    uint8_t w[5] = {1,2,3,4,5};
    size_t n = rb_write(rb, w, 5);
    if (n != 5) { printf("FAIL: write %zu\n", n); return 1; }
    if (rb_size(rb) != 5) { printf("FAIL: size after write\n"); return 1; }

    /* Peek */
    uint8_t peek[3];
    if (rb_peek(rb, peek, 3) != 3) { printf("FAIL: peek\n"); return 1; }
    if (peek[0] != 1 || peek[1] != 2 || peek[2] != 3) { printf("FAIL: peek vals\n"); return 1; }

    /* Read & check order */
    uint8_t rbuf[5];
    if (rb_read(rb, rbuf, 5) != 5) { printf("FAIL: read\n"); return 1; }
    for (int i = 0; i < 5; i++) if (rbuf[i] != (uint8_t)(i + 1)) { printf("FAIL: read vals\n"); return 1; }

    /* Underflow / NULL args */
    if (rb_read(NULL, rbuf, 5) != 0) { printf("FAIL: rb_read(NUll)\n"); return 1; }
    if (rb_write(rb, NULL, 5) != 0) { printf("FAIL: rb_write(NUll)\n"); return 1; }

    /* Write more than capacity, expect partial */
    uint8_t big[16] = {0};
    for (int i = 0; i < 16; i++) big[i] = (uint8_t)(i + 50);
    n = rb_write(rb, big, 16);
    if (n != 8) { printf("FAIL: write partial %zu\n", n); return 1; }

    /* Read back */
    uint8_t rbuf2[8];
    rb_read(rb, rbuf2, 8);
    for (int i = 0; i < 8; i++) if (rbuf2[i] != (uint8_t)(i + 50)) { printf("FAIL: read partial vals\n"); return 1; }

    /* Wrap-around test */
    rb_clear(rb);
    uint8_t a[6] = {10,11,12,13,14,15};
    rb_write(rb, a, 6);
    uint8_t out[3];
    rb_read(rb, out, 3); /* removes first 3 */
    /* remaining: 13,14,15 then add more to wrap */
    uint8_t b[5] = {20,21,22,23,24};
    rb_write(rb, b, 5); /* now have 7 bytes, head wraps */
    uint8_t check[7];
    rb_read(rb, check, 7);
    int ok = (check[0]==13 && check[1]==14 && check[2]==15 &&
              check[3]==20 && check[4]==21 && check[5]==22 && check[6]==23);
    if (!ok) { printf("FAIL: wrap-around\n"); return 1; }

    /* Destroy NULL */
    rb_destroy(NULL);

    /* Invalid capacity */
    if (rb_create(0) != NULL) { printf("FAIL: create(0)\n"); return 1; }

    rb_destroy(rb);
    printf("All tests passed.\n");
    return 0;
}

